    | Error es -> Error(es |> List.map (DecodeError.under (PathSegment.Key name)))

// A required declared member: absent (and the hook answering `None`) is `dReq`'s refusal.
let private cReqAt (ov: CollectingDecoders) (holder: string) (j: JVal) (name: string) (fs: (string * JVal) list) (dec: JVal -> Result<'T, DecodeError list>) : Result<'T, DecodeError list> =
    match fs |> List.tryFind (fun (k, _) -> k = name) with
    | Some(_, v) -> dec v |> cUnder (PathSegment.Key name)
    | None -> cAbsent ov holder j name dec (fun () -> cOne (dReq name fs (fun _ -> dFail DecodeCode.SchemaFault "never read" "never read")))

let private cOptAt (ov: CollectingDecoders) (holder: string) (j: JVal) (name: string) (fs: (string * JVal) list) (dec: JVal -> Result<'T, DecodeError list>) : Result<'T option, DecodeError list> =
    match fs |> List.tryFind (fun (k, _) -> k = name) with
    | Some(_, v) -> dec v |> cUnder (PathSegment.Key name) |> Result.map Some
    | None -> cAbsent ov holder j name (dec >> Result.map Some) (fun () -> Ok None)

let private cDefAt (ov: CollectingDecoders) (holder: string) (j: JVal) (name: string) (fs: (string * JVal) list) (dec: JVal -> Result<'T, DecodeError list>) (dflt: 'T) : Result<'T, DecodeError list> =
    match fs |> List.tryFind (fun (k, _) -> k = name) with
    | Some(_, v) -> dec v |> cUnder (PathSegment.Key name)
    | None -> cAbsent ov holder j name dec (fun () -> Ok dflt)

// Phase 562 — the generated decoders at the JSON scalars, each the short-circuiting reader lifted.
let private colString (_: CollectingDecoders) (j: JVal) : Result<string, DecodeError list> = cOne (dStr j)

let private colInt (_: CollectingDecoders) (j: JVal) : Result<int, DecodeError list> = cOne (dInt j)

let private colFloat (_: CollectingDecoders) (j: JVal) : Result<float, DecodeError list> = cOne (dFloat j)

let private colBool (_: CollectingDecoders) (j: JVal) : Result<bool, DecodeError list> = cOne (dBool j)

// Phase 562 — the generated `Absent`: every absent member reads by its presence rule.
let private colAbsent (_: CollectingDecoders) (_: string) (_: string) (_: JVal) : Result<JVal option, DecodeError list> = Ok None

let rec private colNodeKind (__ov: CollectingDecoders) (j: JVal) : Result<NodeKind, DecodeError list> =
    cObj j |> Result.bind (fun __fs ->
    dTag __fs |> cOne |> Result.bind (fun __t ->
    match __t with
    | "Defaults" -> __ov.DefaultsSpec __ov j |> Result.map NodeKind.Defaults
    | __other -> cOne (dUnknown "one of 'Defaults'" ("$type '" + __other + "'"))))

and private colNode (__ov: CollectingDecoders) (j: JVal) : Result<Node, DecodeError list> =
    cObj j |> Result.bind (fun __fs ->
        let __c0 = cOne (dReq "id" __fs dStr)
        let __c1 = cReq "kind" __fs (colNodeKind __ov)
        match __c0, __c1 with
        | Ok id, Ok kind ->
            Ok { Id = id; Kind = kind }
        | _ -> Error(List.concat [ cErrs __c0; cErrs __c1 ]))

and private colPick<'T> (__ov: CollectingDecoders) (colT: JVal -> Result<'T, DecodeError list>) (instT: Instantiation<'T>) (j: JVal) : Result<Pick<'T>, DecodeError list> =
    let decT (__j: JVal) = cFirst (colT __j)
    match j with
    | JObj __fs ->
        dTag __fs |> cOne |> Result.bind (fun __t ->
        match __t with
        | "Held" ->
            let __holder = "Pick.Held"
            let __c0 = cDefAt __ov __holder j "inner" __fs (fun __j -> __ov.Tagged.Decode(__ov, colT, instT, __j)) ({ Tag = ""; Items = [] })
            let __c1 = cReqAt __ov __holder j "x" __fs (__ov.Int __ov)
            match __c0, __c1 with
            | Ok inner, Ok x ->
                Ok(Pick.Held(inner, x))
            | _ -> Error(List.concat [ cErrs __c0; cErrs __c1 ])
        | "Carried" ->
            let __holder = "Pick.Carried"
            let __c0 = colMembersLaid __ov colT instT j __fs
            match __c0 with
            | Ok payload ->
                Ok(Pick.Carried(payload))
            | _ -> Error(List.concat [ cErrs __c0 ])
        | "Bare" -> Ok Pick.Bare
        | __other -> cOne (dUnknown "one of 'Held', 'Carried', 'Bare'" ("$type '" + __other + "'")))
    | __j -> cOne (Error(Decoder.wrongKind "object" __j))

and private colFormat (__ov: CollectingDecoders) (j: JVal) : Result<Format, DecodeError list> =
    match j with
    | JObj __fs ->
        dTag __fs |> cOne |> Result.bind (fun __t ->
        match __t with
        | "Plain" -> Ok Format.Plain
        | "Custom" ->
            let __holder = "Format.Custom"
            let __c0 = cReqAt __ov __holder j "render" __fs (cLift (fun (__j: JVal) -> dSentinel "<closure>" __j |> Result.map (fun () -> (fun (_: obj) -> ""))))
            match __c0 with
            | Ok render ->
                Ok(Format.Custom(render))
            | _ -> Error(List.concat [ cErrs __c0 ])
        | __other -> cOne (dUnknown "one of 'Plain', 'Custom'" ("$type '" + __other + "'")))
    | __j -> cOne (Error(Decoder.wrongKind "object" __j))

and private colTagged<'T> (__ov: CollectingDecoders) (colT: JVal -> Result<'T, DecodeError list>) (instT: Instantiation<'T>) (j: JVal) : Result<Tagged<'T>, DecodeError list> =
    let decT (__j: JVal) = cFirst (colT __j)
    let __holder = "Tagged"
    cObj j |> Result.bind (fun __fs ->
        let __c0 = cDefAt __ov __holder j "tag" __fs (__ov.String __ov) ("")
        let __c1 = cDefAt __ov __holder j "items" __fs (cList colT) ([])
        match __c0, __c1 with
        | Ok tag, Ok items ->
            Ok { Tag = tag; Items = items }
        | _ -> Error(List.concat [ cErrs __c0; cErrs __c1 ]))

and private colTwin<'T> (__ov: CollectingDecoders) (colT: JVal -> Result<'T, DecodeError list>) (instT: Instantiation<'T>) (j: JVal) : Result<Twin<'T>, DecodeError list> =
    let decT (__j: JVal) = cFirst (colT __j)
    let __holder = "Twin"
    cObj j |> Result.bind (fun __fs ->
        let __c0 = cReqAt __ov __holder j "tag" __fs (__ov.Int __ov)
        let __c1 = cReqAt __ov __holder j "items" __fs (cList (__ov.Int __ov))
        let __c2 = cReqAt __ov __holder j "extra" __fs colT
        match __c0, __c1, __c2 with
        | Ok tag, Ok items, Ok extra ->
            Ok { Tag = tag; Items = items; Extra = extra }
        | _ -> Error(List.concat [ cErrs __c0; cErrs __c1; cErrs __c2 ]))

and private colOuter<'T> (__ov: CollectingDecoders) (colT: JVal -> Result<'T, DecodeError list>) (instT: Instantiation<'T>) (j: JVal) : Result<Outer<'T>, DecodeError list> =
    let decT (__j: JVal) = cFirst (colT __j)
    let __holder = "Outer"
    cObj j |> Result.bind (fun __fs ->
        let __c0 = cDefAt __ov __holder j "inner" __fs (fun __j -> __ov.Tagged.Decode(__ov, colT, instT, __j)) ({ Tag = ""; Items = [] })
        let __c1 = cReqAt __ov __holder j "x" __fs (__ov.Int __ov)
        match __c0, __c1 with
        | Ok inner, Ok x ->
            Ok { Inner = inner; X = x }
        | _ -> Error(List.concat [ cErrs __c0; cErrs __c1 ]))

and private colDefaultsSpec (__ov: CollectingDecoders) (j: JVal) : Result<DefaultsSpec, DecodeError list> =
    let __holder = "DefaultsSpec"
    cObj j |> Result.bind (fun __fs ->
        let __c0 = cReqAt __ov __holder j "outer" __fs (fun __j -> __ov.Outer.Decode(__ov, (__ov.Float __ov), Instantiation.Float(id, id), __j))
        let __c1 = cOptAt __ov __holder j "choice" __fs (fun __j -> __ov.Pick.Decode(__ov, (__ov.Int __ov), Instantiation.Int(id, id), __j))
        let __c2 = colMembersLaid __ov (__ov.String __ov) (Instantiation.String(id, id)) j __fs
        let __c3 = cDefAt __ov __holder j "format" __fs (fun __j -> __ov.Tagged.Decode(__ov, (__ov.Format __ov), Instantiation.Format(id, id), __j)) ({ Tag = ""; Items = [] })
        let __c4 = cOptAt __ov __holder j "twin" __fs (fun __j -> __ov.Twin.Decode(__ov, (__ov.String __ov), Instantiation.String(id, id), __j))
        match __c0, __c1, __c2, __c3, __c4 with
        | Ok outer, Ok choice, Ok laid, Ok format, Ok twin ->
            Ok { Outer = outer; Choice = choice; Laid = laid; Format = format; Twin = twin }
        | _ -> Error(List.concat [ cErrs __c0; cErrs __c1; cErrs __c2; cErrs __c3; cErrs __c4 ]))

and private colMembersLaid<'T> (__ov: CollectingDecoders) (colT: JVal -> Result<'T, DecodeError list>) (instT: Instantiation<'T>) (j: JVal) (__fs: (string * JVal) list) : Result<Laid<'T>, DecodeError list> =
    let decT (__j: JVal) = cFirst (colT __j)
    let __holder = "Laid"
    let __c0 = cDefAt __ov __holder j "inner" __fs (fun __j -> __ov.Tagged.Decode(__ov, colT, instT, __j)) ({ Tag = ""; Items = [] })
    let __c1 = cReqAt __ov __holder j "y" __fs (__ov.Int __ov)
    match __c0, __c1 with
    | Ok inner, Ok y ->
        Ok { Inner = inner; Y = y }
    | _ -> Error(List.concat [ cErrs __c0; cErrs __c1 ])

/// Phase 541 — the generated collecting decoders: what every `decode*All` entry reads through, and
/// the record a host copies (`{ collectingDecoders with <Type> = … }`) to override one type.
let collectingDecoders: CollectingDecoders =
    { Node = colNode
      Format = colFormat
      DefaultsSpec = colDefaultsSpec
      String = colString
      Int = colInt
      Float = colFloat
      Bool = colBool
      Pick =
        { new CollectingPick with
            member _.Decode(__ov, colT, instT, j) = colPick __ov colT instT j }
      Tagged =
        { new CollectingTagged with
            member _.Decode(__ov, colT, instT, j) = colTagged __ov colT instT j }
      Twin =
        { new CollectingTwin with
            member _.Decode(__ov, colT, instT, j) = colTwin __ov colT instT j }
      Outer =
        { new CollectingOuter with
            member _.Decode(__ov, colT, instT, j) = colOuter __ov colT instT j }
      Absent = colAbsent }

/// Phase 377 — the public per-spec decoders. `decode<Tag>Spec` reads one kind's object and
/// answers its FIRST defect; `decode<Tag>SpecAll` reads the same object and answers EVERY defect,
/// in the order stated above the collecting prelude. A consumer delegates one kind at a time.
/// Phase 541 — `decode<Tag>SpecAllWith` reads it through a host's `CollectingDecoders`, so the
/// host's decoder at a type applies at every depth; `decode<Tag>SpecAll` is its no-override case.
let decodeDefaultsSpec (j: JVal) : Result<DefaultsSpec, DecodeError> = decDefaultsSpec j
let decodeDefaultsSpecAll (j: JVal) : Result<DefaultsSpec, DecodeError list> = colDefaultsSpec collectingDecoders j
let decodeDefaultsSpecAllWith (decoders: CollectingDecoders) (j: JVal) : Result<DefaultsSpec, DecodeError list> =
    decoders.DefaultsSpec decoders j
/// The whole node over a parsed value: the first defect, or every defect.
let decodeNodeJson (j: JVal) : Result<Node, DecodeError> = decNode j
let decodeNodeJsonAll (j: JVal) : Result<Node, DecodeError list> = colNode collectingDecoders j
let decodeNodeJsonAllWith (decoders: CollectingDecoders) (j: JVal) : Result<Node, DecodeError list> =
    decoders.Node decoders j
/// `decodeNode`'s collecting twin: a parser refusal is the one defect, else every defect.
let decodeNodeAll (s: string) : Result<Node, DecodeError list> =
    Decoder.parse ReadOptions.strict s |> cOne |> Result.bind (colNode collectingDecoders)
let decodeNodeAllWith (decoders: CollectingDecoders) (s: string) : Result<Node, DecodeError list> =
    Decoder.parse ReadOptions.strict s |> cOne |> Result.bind (decoders.Node decoders)